3	import org.apache.logging.log4j.LogManager;
4	import org.apache.logging.log4j.Logger;
5	
6	/**
7	 * Minimal order intake service. Every accepted order is written to the audit log
8	 * so downstream reconciliation can replay the intake stream.
9	 */
10	public class OrderService {
11	    private static final Logger LOG = LogManager.getLogger(OrderService.class);
12	
13	    public String process(String orderId) {
14	        LOG.info("processing order {}", orderId);
15	        return "processed:" + orderId;
16	    }
17	
18	    public static void main(String[] args) {
19	        OrderService svc = new OrderService();
20	        String orderId = args.length > 0 ? args[0] : "A-1001";
21	        System.out.println(svc.process(orderId));
22	    }
23	}
